+const ctx: EvalContext = { properties: jobs, viewer: testViewer(), userName: () => undefined };
+const rule = (
+  id: string,
+  propertyId: string,
+  op: FilterOp,
+  value?: FilterValue,
+): FilterCondition =>
+  value === undefined
+    ? { kind: 'condition', id, propertyId, op }
+    : { kind: 'condition', id, propertyId, op, value };
+const group = (
+  id: string,
+  children: FilterNode[],
+  combinator: 'and' | 'or' = 'and',
