+  it('checks nothing while they are off', () => {
+    expect(testHooksEnabled(load({ HOST: '0.0.0.0' }))).toBe(false);
+    expect(
+      testHooksEnabled(
+        load({ CAREHUB_TEST_HOOKS: '0', CAREHUB_PUBLIC_URL: 'https://carehub.example.test' }),
+      ),
+    ).toBe(false);
+  });
