+    for (const url of [
+      '/api/push/test',
+      '/api/test/private',
+      '/api/learning/tests/x',
+      '/api/learning/courses/test/x',
+      '/test/x',
+      '/learning/test/x',
+    ]) {
+      expect(isTestHookRoute(url), url).toBe(false);
+    }
+  });
