+    [PROPS.due, 'within', 'past_7_days', 'Due date is within Past 7 days'],
+    [
+      PROPS.due,
+      'within',
+      { direction: 'next', count: 3, unit: 'week' },
+      'Due date is within Next 3 weeks',
