+    } finally {
+      await close();
+    }
+  });
+
+  it('refuses to start with a test hook while they are off', async () => {
+    const routes = (app: FastifyInstance) => {
+      app.post('/api/example/test/thing', async () => ({ ok: true }));
+    };
+    await expect(createTestApp({ routes })).rejects.toThrow(
