+  value === undefined
+    ? { kind: 'condition', id, propertyId, op }
+    : { kind: 'condition', id, propertyId, op, value };
+const group = (
+  id: string,
+  children: FilterNode[],
+  combinator: 'and' | 'or' = 'and',
