+import { describe, expect, it } from 'vitest';
+import { ME, type EvalContext, type Property } from '@carehub/databases';
+import { jobsProperties, PROPS, STATUS, testViewer, USERS } from '../fixtures';
+import { newRule } from './filter-model';
+import { windowLabel } from './messages';
+import { ruleText } from './rule-text';
+
+const props = jobsProperties();
+const prop = (id: string): Property => {
+  const found = props.find((p) => p.id === id);
+  if (!found) throw new Error(`No property ${id}`);
+  return found;
+};
+const ctx: EvalContext = {
+  properties: props,
+  viewer: testViewer(),
+  userName: (id) => (id === USERS.jordan.id ? USERS.jordan.name : undefined),
+  rowTitle: () => undefined,
+};
+
+describe('ruleText', () => {
+  const text = (id: string, op: string, value?: unknown) =>
+    ruleText({ kind: 'condition', id: 'r', propertyId: id, op, value } as never, prop(id), ctx);
+
+  const cases: [string, string, unknown, string][] = [
+    [PROPS.status, 'is', [STATUS.done, STATUS.inProgress], 'Status is Done, In progress'],
+    [PROPS.status, 'group_is', ['complete'], 'Status group is Complete'],
+    [PROPS.paid, 'is_checked', undefined, 'Paid is ticked'],
+    [
+      PROPS.technician,
+      'contains_any',
+      [ME, USERS.jordan.id],
+      'Technician contains any of Me, Jordan Park',
+    ],
+    [PROPS.technician, 'contains_any', ['user-gone'], 'Technician contains any of Unknown person'],
+    [PROPS.due, 'within', 'past_7_days', 'Due date is within Past 7 days'],
+    [
+      PROPS.due,
+      'within',
+      { direction: 'next', count: 3, unit: 'week' },
+      'Due date is within Next 3 weeks',
+    ],
+    [PROPS.due, 'before', { exact: '2026-10-30' }, 'Due date is before Oct 30, 2026'],
+    [
+      PROPS.due,
+      'between',
+      { start: { relative: 'today' }, end: { relative: 'one_week_from_now' } },
+      'Due date is between Today → One week from now',
+    ],
+    [PROPS.cost, 'gte', '100', 'Cost at least $100.00'],
+    [PROPS.notes, 'contains', 'mornings', 'Notes contains mornings'],
+    [PROPS.notes, 'is_empty', undefined, 'Notes is empty'],
+  ];
+  it.each(cases)('%s %s %j reads "%s"', (id, op, value, want) => {
+    expect(text(id, op, value)).toBe(want);
+  });
+
+  it('says when the property was deleted', () => {
+    expect(ruleText(newRule(prop(PROPS.paid)), undefined, ctx)).toBe('This property was deleted.');
+  });
+
+  it('names custom windows', () => {
+    expect(windowLabel({ direction: 'past', count: 1, unit: 'day' })).toBe('Past 1 day');
+    expect(windowLabel('this_month')).toBe('This month');
+  });
+});
diff --git a/apps/web/src/features/databases/filters/rule-text.ts b/apps/web/src/features/databases/filters/rule-text.ts
new file mode 100644
index 0000000..7e593e9
--- /dev/null
+++ b/apps/web/src/features/databases/filters/rule-text.ts
@@ -0,0 +1,92 @@
+/**
+ * A filter rule in words, for the filter chips and the advanced filter's rows (Databases spec
+ * 3.2): "Status is Done, In progress", "Technician contains any of Me", "Due date is within Past
+ * 7 days". Condition names come from the package.
+ */
+import {
+  formatCalendarDate,
+  ME,
+  type DateRef,
+  type DateWindow,
+  type EvalContext,
+  type FilterCondition,
+  type Id,
+  type Property,
+  type StatusGroup,
+} from '@carehub/databases';
+import { filterOpLabel, filterValueKind } from '@carehub/databases/filter';
+import { STATUS_GROUP_LABELS } from '@carehub/databases/group';
+import { formatValue } from '@carehub/databases/values';
+import { FILTER_TEXT, RELATIVE_DAY_LABELS, WINDOW_LABELS, windowLabel } from './messages';
+
+const idsOf = (v: unknown): Id[] =>
+  Array.isArray(v) ? v.filter((x): x is Id => typeof x === 'string') : [];
+
+export function dateRefText(ref: DateRef): string {
+  return 'relative' in ref
+    ? RELATIVE_DAY_LABELS[ref.relative]
+    : formatCalendarDate(ref.exact, 'full');
+}
+
+const isRef = (v: unknown): v is DateRef =>
+  typeof v === 'object' && v !== null && ('relative' in v || 'exact' in v);
+
+const isWindow = (v: unknown): v is DateWindow =>
+  typeof v === 'string'
+    ? Object.hasOwn(WINDOW_LABELS, v)
+    : typeof v === 'object' && v !== null && 'unit' in v && 'count' in v && 'direction' in v;
+
+/** A rule's value in words ("Done, In progress", "Me", "Today", "Past 7 days"); "" without one. */
+export function valueText(rule: FilterCondition, prop: Property, ctx: EvalContext): string {
+  const v = rule.value;
+  if (v === undefined) return '';
+  const config = prop.config;
+  switch (filterValueKind(prop, rule.op)) {
+    case 'text':
+      return typeof v === 'string' ? v : '';
+    case 'number':
+      return typeof v !== 'string' ? '' : config.type === 'number' ? formatValue(prop, v, ctx) : v;
+    case 'options': {
+      const options = 'options' in config ? config.options : [];
+      return idsOf(v)
+        .map((id) => options.find((o) => o.id === id)?.name)
+        .filter((name): name is string => name !== undefined)
+        .join(', ');
+    }
+    case 'status_groups':
+      return idsOf(v)
+        .map((g) => STATUS_GROUP_LABELS[g as StatusGroup])
+        .filter((label): label is string => label !== undefined)
+        .join(', ');
+    case 'people':
+      return idsOf(v)
+        .map((id) => (id === ME ? FILTER_TEXT.me : (ctx.userName(id) ?? FILTER_TEXT.unknownPerson)))
+        .join(', ');
+    case 'rows':
+      return idsOf(v)
+        .map((id) => ctx.rowTitle?.(id) || FILTER_TEXT.untitled)
+        .join(', ');
+    case 'date':
+      return isRef(v) ? dateRefText(v) : '';
+    case 'date_range':
+      return typeof v === 'object' && 'start' in v && isRef(v.start) && isRef(v.end)
+        ? `${dateRefText(v.start)} → ${dateRefText(v.end)}`
+        : '';
+    case 'date_window':
+      return isWindow(v) ? windowLabel(v) : '';
+    case 'none':
+      return '';
+  }
+}
+
+/** What a filter chip says: "Status is Done, In progress", "Paid is ticked", "Due date is within This week". */
+export function ruleText(
+  rule: FilterCondition,
+  prop: Property | undefined,
+  ctx: EvalContext,
+): string {
+  if (!prop) return FILTER_TEXT.deletedProperty;
+  const op = filterOpLabel(rule.op).toLowerCase();
+  const value = valueText(rule, prop, ctx);
+  return value ? `${prop.name} ${op} ${value}` : `${prop.name} ${op}`;
+}
